mapper.select:
select comment.id as id, comment.course_id as courseId, comment.teacher_id as teacherId, comment.uid as uid, comment.content as content, comment.mark as mark, comment.create_time as createTime, comment.update_time as updateTime, u.nickname as nickname, u.avatar as avatar, c.title as courseTitle, t.name as teacherName from edu_comment comment left join acl_user u on comment.uid = u.id left join edu_course c on comment.course_id = c.id left join edu_teacher t on comment.teacher_id = t.id where comment.is_deleted = 0
and u.nickname like concat('%',#{comment.nickname},'%')
and comment.reported = #{comment.reported}
and comment.course_id = #{comment.courseId}
and comment.uid = #{comment.uid}
and comment.teacher_id = #{comment.teacherId}
and comment.create_time > date_format(#{comment.startTime},'%Y-%m-%d %H:%i:%s') and comment.create_time < date_format(#{comment.endTime},'%Y-%m-%d %H:%i:%s')
order by comment.create_time desc
